"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 step 2d: a read-out that keeps time (docs/iterations.md, 2026-11-20: design, replacement rule and expectations
logged before running; the author chose option B). Exploratory; local; dev for evaluation; test and replication untouched.

Why: the time-resolved ears diagnostic (scripts/p1v4_ears_time_diag.py, p1v4_ears_time_control.py) found that the stop
scenes' information is in the audio encoder second by second (per-second probe 0.82 vs 0.58 for the whole-window
summary on the S-move groups) and is lost when the seconds are shuffled (0.64); the respond scenes do not need time.

Design: per question (S, R) a logistic regression on the last-layer states at the two option positions (2,048, as in
2b/2c) plus the per-second ears of its window (mean and max of the 13 encoder tokens of each of the 8 seconds; 16,384),
trained on the step 2c train forward (timing-matched false labels) exactly as the 2c fit (same holdout units, weight
decay grid, optimiser). Thresholds by the plan's operating-point rule on natural dev.
Commands:
  ears     per-second ears of every train window (encoder only, batch 8); check against the stored ears
  fit      the two read-outs
  eval     dev: natural operating point and metrics, matched R-hear and S-move groups in every condition (score and
           decision level), grounded with intervals, replacement-rule items 1-3
  offsets  the 72 dev S-move groups re-rendered and cut at -0.5, 0, +0.5, +1.0 s around the decision point; L1 forward
           (batch 1) with the matched "none" text; 2d, 2c ears, 2b ears and the old head per offset; rule item 4
  report   decision-table rehearsal (Gemini on probabilities and on answers) and natural comparisons
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_readout_2d.py ears|fit|eval|offsets|report
Outputs: data/p1v4/runs/grounding/allclass2d/; results/main_v04/readout_2d_dev.json, offsets_2d_dev.json,
decision_dev_dryrun_2d{,_answers}.json, readout_2d_natural_dev.json
"""
import copy
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_ears_time_diag as ET  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_readout_2c as R2C  # noqa: E402
import p1v4_readout_allclass as AC  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/grounding/allclass2d"
RES = "results/main_v04"
DEV_SEC = "data/p1v4/runs/ears_time/feats_dev.npz"        # = p1v4_ears_time_diag.OUT
OFFSETS = (-0.5, 0.0, 0.5, 1.0)


def per_second(model_vt, waves):
    """Audio tokens (B, 104, d) -> per-second mean and max (B, 8, d) each, float32 numpy, and the whole-window ears."""
    import torch
    with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
        audio = model_vt.encode_audio(model_vt.mel(waves))
    a = audio.float()
    assert a.shape[1] == 104, a.shape
    s = a.view(a.shape[0], 8, 13, a.shape[2])
    return (s.mean(2).cpu().numpy(), s.amax(2).cpu().numpy(),
            torch.cat([a.mean(1), a.amax(1)], -1).cpu().numpy())


def design(states, sm, sx):
    return np.concatenate([np.asarray(states, dtype=np.float32),
                           ET.pool(np.asarray(sm, dtype=np.float32), np.asarray(sx, dtype=np.float32), "sec8")], 1)


# ------------------------------------------------------------------------------------------------ train

def ears():
    import soundfile as sf
    import torch
    import l1_voxturn
    D.gpu_guard()
    os.makedirs(OUT, exist_ok=True)
    _, vt = l1_voxturn.load_official()
    wins = D.windows_of(D.load_rows("train"), "train")
    SM, SX, WH = [], [], []
    t0 = time.time()
    for i in range(0, len(wins), 8):
        chunk = wins[i:i + 8]
        waves = torch.stack([torch.from_numpy(sf.read(w["path"], dtype="float32")[0]) for w in chunk]).cuda()
        sm, sx, wh = per_second(vt, waves)
        SM.append(sm.astype(np.float16))
        SX.append(sx.astype(np.float16))
        WH.append(wh.astype(np.float16))
        if (i // 8) % 1000 == 0:
            print(f"train: {i + len(chunk)}/{len(wins)} windows {time.time() - t0:.0f} s", flush=True)
    ids = np.array([w["id"] for w in wins])
    z = np.load(f"{R2C.OUT}/feats_train_2c.npz", mmap_mode="r")
    assert np.array_equal(z["ids"], ids), "window order differs from the 2c train forward"
    wh = np.concatenate(WH)
    diff = float(np.abs(wh.astype(np.float32) - np.asarray(z["ears"], dtype=np.float32)).max())
    np.savez(f"{OUT}/sec8_train.npz", ids=ids, sec_mean=np.concatenate(SM), sec_max=np.concatenate(SX))
    json.dump({"n_windows": len(wins), "max_abs_diff_whole_vs_stored_2c_ears": diff, "seconds": time.time() - t0},
              open(f"{OUT}/ears_check.json", "w"), indent=1)
    print(f"train per-second ears: {len(wins)} windows, {time.time() - t0:.0f} s; whole vs stored 2c ears max |diff| "
          f"{diff}", flush=True)


def fit():
    D.gpu_guard()
    z = np.load(f"{R2C.OUT}/feats_train_2c.npz")
    e = np.load(f"{OUT}/sec8_train.npz")
    assert np.array_equal(z["ids"], e["ids"])
    units = z["units"][z["q_win"]]
    rng = np.random.default_rng(RO.SEED)                    # the same holdout units as the 2c fit
    uniq = np.unique(z["units"])
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    hold = np.array([u in hold_units for u in units])
    sm_all, sx_all = e["sec_mean"], e["sec_max"]
    log, models = {}, {}
    for q in ("S", "R"):
        m = np.where((z["q_task"] == q) & (z["q_gold"] >= 0))[0]
        wq = z["q_win"][m]
        X = design(z["states"][m], sm_all[wq], sx_all[wq])
        mu, sd = X.mean(0), X.std(0) + 1e-6
        X -= mu
        X /= sd
        Xh = X.astype(np.float16)
        del X
        y = z["q_gold"][m]
        hm = hold[m]
        best = None
        for wd in RO.WDS:
            lin = RO.train_logreg(Xh[~hm], y[~hm], wd)
            p = np.clip(RO.predict(lin, Xh[hm]), 1e-7, 1 - 1e-7)
            yy = y[hm]
            ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
            log[f"ears8 {q} wd {wd}"] = ll
            print(f"2d ears8 {q} wd {wd}: holdout log loss {ll:.4f}", flush=True)
            if best is None or ll < best[0]:
                best = (ll, wd)
        lin = RO.train_logreg(Xh, y, best[1])
        models[q] = {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
                     "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1]}
        del Xh
    np.savez(f"{OUT}/readouts_2d.npz", **{f"ears8|{q}|{f}": v for q, d in models.items() for f, v in d.items()})
    json.dump(log, open(f"{OUT}/fit_log.json", "w"), indent=1)
    print("2d read-outs fitted:", {q: d["wd"] for q, d in models.items()}, flush=True)


def load_2d():
    z = np.load(f"{OUT}/readouts_2d.npz")
    out = {}
    for k in z.files:
        _, q, f = k.split("|")
        out.setdefault(q, {})[f] = z[k]
    return out


class Sec:
    """Per-second ears looked up by window id."""

    def __init__(self, path=DEV_SEC, ids=None, sm=None, sx=None):
        if path is not None:
            z = np.load(path)
            ids, sm, sx = z["ids"], z["sec_mean"], z["sec_max"]
        self.pos = {i: n for n, i in enumerate(ids)}
        self.sm, self.sx = sm, sx

    def rows(self, ids):
        return [self.pos[i] for i in ids]


def scores_2d(z, sec, ro):
    """{(unit, version, k): {"S": p, "R": p}} from the 2d read-out; z holds states, q_win, q_task, ids."""
    sc = {}
    wid = z["ids"][z["q_win"]]
    p = np.zeros(len(z["q_task"]))
    for q in ("S", "R"):
        m = np.where(z["q_task"] == q)[0]
        if not len(m):
            continue
        r = sec.rows(wid[m])
        X = design(z["states"][m], sec.sm[r], sec.sx[r])
        lg = ((X - ro[q]["mu"]) / ro[q]["sd"]) @ ro[q]["w"] + float(ro[q]["b"])
        p[m] = 1 / (1 + np.exp(-lg))
    for w, q, x in zip(z["q_win"], z["q_task"], p):
        i = z["ids"][w].split("|")
        sc.setdefault((i[0], i[1], int(i[2])), {})[str(q)] = float(x)
    return sc


# ------------------------------------------------------------------------------------------------ dev

def eval_():
    import p1v4_grounding as G
    import p1v4_grounding_report as GR
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    groups_map = S.load_groups("dev")
    ro, sec = load_2d(), Sec()
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    sc = scores_2d(zn, sec, ro)
    json.dump({f"{u}|{v}|{k}": x for (u, v, k), x in sc.items()}, open(f"{RO.OUT}/scores_dev_2d.json", "w"))
    op = S.operating_point(rows, sc)
    th = {"S": op["th_s"], "R": op["th_r"]}
    T = S.unit_table(rows, S.decide(sc, th["S"], th["R"]), groups_map)
    m = S.metrics(T)
    res = {"natural": {"th": th, "primary": m["primary"], "parts": m["parts"], "floors": m["floors"],
                       "floors_met": op["floors_met"], "audio": m["audio"]}, "matched": {}, "pairs": {}}
    evs, evd = {}, {}
    for cond in G.CONDS:
        z = dict(np.load(f"{G.out_dir('dev')}/l1_{cond}.npz"))
        s = scores_2d(z, sec, ro)
        dec = S.decide(s, th["S"], th["R"])
        evs[cond] = GR.group_eval(groups, rows_by, dec, s)
        evd[cond] = GR.group_eval(groups, rows_by, dec, None)
    for part in ("r_hear", "s_move"):
        for level, ev in (("score", evs), ("decision", evd)):
            summ = {c: GR.summarise(ev[c], part) for c in G.CONDS}
            mm = [summ[c] for c in G.MATCHED]
            res["matched"].setdefault(level, {})[part] = {
                "by_condition": summ, "mean_matched": {f: float(np.mean([x[f] for x in mm]))
                                                       for f in ("right", "conc", "follow_event", "follow_none")}}
            res["pairs"].setdefault(level, {})[part] = {
                f"conc_1_vs_{v}": float(np.mean([summ[c][f"conc_1_vs_{v}"] for c in G.MATCHED]))
                for v in ("2", "3", "4") if f"conc_1_vs_{v}" in summ[G.MATCHED[0]]}
    cl = GR.cluster_table(rows, "dev")
    crit = {}
    for part in ("r_hear", "s_move"):
        us = [g["unit"] for g in groups if g["part"] == part]
        a = np.array([np.mean([evs[c][u]["right"] for c in G.MATCHED]) for u in us])
        c = GR.criterion(us, cl, {}, lambda w, a=a: GR.wmean(w, a), lambda a=a: float(a.mean()))
        crit[part] = {"point": c["point"], "ci95": c["ci95"]}
    res["grounded_with_intervals"] = crit
    r_ok = crit["r_hear"]["point"] >= 0.65 and crit["r_hear"]["ci95"][0] > 0.5
    res["rule"] = {"1 respond: R-hear grounded >= 0.65, lower bound > 0.5": [crit["r_hear"], r_ok],
                   "2 stop: S-move grounded >= 0.70": [crit["s_move"]["point"], crit["s_move"]["point"] >= 0.70],
                   "3 natural five-part >= 0.934, floors met": [m["primary"], m["primary"] >= 0.934
                                                                and op["floors_met"]]}
    json.dump(res, open(f"{RES}/readout_2d_dev.json", "w"), indent=1)
    n = res["natural"]
    print(f"natural 2d: five-part {n['primary']:.4f} audio {n['audio']:.3f} th {th} floors "
          + " ".join(f"{k}:{v:.2f}" for k, v in n["floors"].items()) + f" met {n['floors_met']}")
    print("parts:", {k: round(v, 3) for k, v in n["parts"].items()})
    for level in ("score", "decision"):
        for part in ("r_hear", "s_move"):
            mm = res["matched"][level][part]["mean_matched"]
            print(f"matched {level:8s} {part:7s} grounded {mm['right']:.3f} conc {mm['conc']:.3f} hit "
                  f"{mm['follow_event']:.2f} false alarms {mm['follow_none']:.2f} pairs {json.dumps(res['pairs'][level][part])}")
    print("grounded with intervals:", json.dumps(crit))
    for k, v in res["rule"].items():
        print(f"rule {k}: {v}")


def offsets(split="dev"):
    """The decision-offset check (G4b). split: dev, or test / replication after the freeze (added 2026-11-20, code
    step 6: thresholds from the freeze record, the rehearsal record on dev; main-body groups only; windows under
    data/p1v4/runs/final/<split>/offsets; output results/main_v04/offsets_2d_<split>.json)."""
    import soundfile as sf
    import torch
    import p1v4_freeze as FZ
    import p1v4_grounding as G
    import p1v4_grounding_report as GR
    import p1v4_l1 as L1
    import p1v4_units as U
    st = json.load(open(FZ.REHEARSAL))["settings"] if split == "dev" else FZ.verify_or_stop()["settings"]
    D.gpu_guard()
    rows, rows_by = G.load(split)
    groups = [g for g in G.load_groups(split) if g["part"] == "s_move" and rows_by[(g["unit"], "1")]["subset"] is None]
    A = U.Assets(split)
    od = f"{R}/final/{split}/offsets"
    os.makedirs(od, exist_ok=True)
    items = []
    for g in groups:
        spec = copy.deepcopy(rows_by[(g["unit"], "1")]["spec"])
        tls = U.BUILDERS["s_move"](spec, A)
        audio, _ = U.render_versions(spec, tls, A)
        for v in g["versions"]:
            p = rows_by[(g["unit"], v)]["points"][g["k"]]
            for d in OFFSETS:
                w = U.windows(audio[v], [{"t": p["t"] + d}])[0]
                assert len(w) == int(D.WIN_S * D.SR), (g["unit"], v, d, len(w))
                if d == 0:
                    assert np.array_equal(w, sf.read(p["window"], dtype="int16")[0]), (g["unit"], v)
                path = f"{od}/{g['unit']}_{v}_p{g['k']}_d{d:+.1f}.wav"
                sf.write(path, w, U.SR, subtype="PCM_16")
                items.append({"unit": g["unit"], "v": v, "k": g["k"], "d": d, "path": path,
                              "marker": "agent" if p.get("assistant_speaking") else "user"})
    print(f"rendered {len(items)} windows ({len(groups)} groups x 4 versions x {len(OFFSETS)} offsets); the original "
          f"offset reproduces the stored windows", flush=True)
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    ctx = G.matched_context(C.Context)(split, groups, "none", rows_by)
    feats = {d: {"H": [], "E": [], "SM": [], "SX": [], "QW": [], "QT": [], "PO": [], "ids": []} for d in OFFSETS}
    t0 = time.time()
    for n, it in enumerate(items):
        r = rows_by[(it["unit"], it["v"])]
        text, asks = ctx.situation(r, it["k"], "full")
        qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
        wave = torch.from_numpy(sf.read(it["path"], dtype="float32")[0])[None].cuda()
        h, e, qw, po = RO.forward_states(model, wave, [text], [it["marker"]], [[RO.TASK[q] for q in qs]])
        sm, sx, _ = per_second(model.vt, wave)
        f = feats[it["d"]]
        f["QW"].append(qw + len(f["ids"]))
        f["ids"].append(f"{it['unit']}|{it['v']}|{it['k']}")
        f["H"].append(h)
        f["E"].append(e)
        f["SM"].append(sm)
        f["SX"].append(sx)
        f["QT"] += qs
        f["PO"].append(po)
        if n % 200 == 0:
            print(f"offsets: {n + 1}/{len(items)} windows {time.time() - t0:.0f} s", flush=True)
    th_all = {"old head": (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"])}
    n2b = {"S": st["readouts"]["2b ears"]["th_s"], "R": st["readouts"]["2b ears"]["th_r"]}
    n2c = {"S": st["readouts"]["2c ears"]["th_s"], "R": st["readouts"]["2c ears"]["th_r"]}
    n2d = {"S": st["main"]["th_s"], "R": st["main"]["th_r"]}
    ro_2b, ro_2c, ro_2d = AC.load_allclass(), R2C.load_2c(), load_2d()
    cl = GR.cluster_table(rows, split)
    units = [g["unit"] for g in groups]
    res, right = {"n_groups": len(groups), "offsets_after_door_onset_s": [1.0 + d for d in OFFSETS], "by_offset": {}}, {}
    for d in OFFSETS:
        f = feats[d]
        z = {"states": np.concatenate(f["H"]), "ears": np.concatenate(f["E"]), "q_win": np.concatenate(f["QW"]),
             "q_task": np.array(f["QT"]), "p_old": np.concatenate(f["PO"]), "ids": np.array(f["ids"])}
        sec = Sec(None, z["ids"], np.concatenate(f["SM"]), np.concatenate(f["SX"]))
        systems = {"2d": (scores_2d(z, sec, ro_2d), (n2d["S"], n2d["R"])),
                   "2c ears": (RO.scores_of(z, "ears", ro_2c), (n2c["S"], n2c["R"])),
                   "2b ears": (RO.scores_of(z, "ears", ro_2b), (n2b["S"], n2b["R"])),
                   "old head": (RO.scores_of(z, None, None), th_all["old head"])}
        res["by_offset"][f"{1.0 + d:.1f} s"] = {}
        for name, (sc, th) in systems.items():
            ev = GR.group_eval(groups, rows_by, S.decide(sc, *th), sc)
            right[(name, d)] = np.array([ev[u]["right"] for u in units])
            res["by_offset"][f"{1.0 + d:.1f} s"][name] = {
                "group_all_right": float(right[(name, d)].mean()),
                "hit_v1": float(np.mean([ev[u]["follow_event"] for u in units])),
                "false_alarms_v2_4": float(np.mean([ev[u]["follow_none"] for u in units])),
                "concordance": float(np.mean([ev[u]["conc"] for u in units]))}
    shifted = [d for d in OFFSETS if d != 0.0]
    a = np.mean([right[("2d", d)] for d in shifted], 0)
    b = np.mean([right[("2c ears", d)] for d in shifted], 0)
    c = GR.criterion(units, cl, {}, lambda w: GR.wmean(w, a) - GR.wmean(w, b), lambda: float(a.mean() - b.mean()))
    g4m = st["grounding"]["g4_margin"]                    # package v0.6 15.3: the margin of the record, and the interval
    res["rule 4: shifted offsets, 2d - 2c ears group all-right >= +0.10"] = {
        "point": c["point"], "ci95": c["ci95"], "ci95_normal": c["ci95_normal"], "df": c["df"],
        "dominant_factor": c["dominant_factor"], "n_clusters": c["n_clusters"], "margin": g4m,
        "pass": bool(c["point"] >= g4m and c["ci95"][0] > 0),
        "note": "all main-body S-move groups; the grounding report (v0.6) recomputes it without identity-dropped groups"}
    res["per_unit_right"] = {name: {f"{d:+.1f}": dict(zip(units, map(float, right[(name, d)]))) for d in OFFSETS}
                             for name in ("2d", "2c ears", "2b ears", "old head")}
    json.dump(res, open(f"{RES}/offsets_2d_{split}.json", "w"), indent=1)
    for off, row in res["by_offset"].items():
        print(f"after door onset {off}: " + " | ".join(
            f"{n} {x['group_all_right']:.3f} (hit {x['hit_v1']:.2f}, fa {x['false_alarms_v2_4']:.2f})"
            for n, x in row.items()), flush=True)
    print("rule 4:", json.dumps(res["rule 4: shifted offsets, 2d - 2c ears group all-right >= +0.10"]), flush=True)


def report():
    import p1v4_grounding_report as GR
    import p1v4_test_report as TR
    rows = D.load_rows("dev")
    th2d = json.load(open(f"{RES}/readout_2d_dev.json"))["natural"]["th"]
    entry = {"kind": "score", "path": f"{RO.OUT}/scores_dev_2d.json", "th_s": th2d["S"], "th_r": th2d["R"]}
    ans = json.load(open(f"{RES}/answer_only_dev.json"))
    base = TR.dev_manifest
    for tag, answers in (("", False), ("_answers", True)):
        def manifest(answers=answers):
            m = base()
            if answers:
                for name in ("B2-fast", "B2-strong", "B3"):
                    c = ans[name]["chosen"]
                    m[name] = {"kind": "score", "path": c["path"], "th_s": c["th_s"], "th_r": c["th_r"]}
            m[TR.OURS] = entry
            return m
        TR.dev_manifest = manifest
        print(f"=== ours = 2d{' (Gemini rivals on answers)' if answers else ''}", flush=True)
        TR.run("dev", f"{RES}/decision_dev_dryrun_2d{tag}.json")
    TR.dev_manifest = base
    sg = S.load_groups("dev")
    th_all = GR.thresholds(rows)
    n2b = json.load(open(f"{RES}/readout_allclass_dev.json"))["natural"]["all-class ears"]["th"]
    n2c = json.load(open(f"{RES}/readout_2c_dev.json"))["natural"]["2c ears"]["th"]
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    nat = {"old head": S.decide(GR.keyed(json.load(open(f"{GR.R}/l1/scores_dev.json"))), *th_all["old head"]),
           "2b ears": S.decide(RO.scores_of(zn, "ears", AC.load_allclass()), n2b["S"], n2b["R"]),
           "2c ears": S.decide(RO.scores_of(zn, "ears", R2C.load_2c()), n2c["S"], n2c["R"]),
           "2d": S.decide(GR.keyed(json.load(open(f"{RO.OUT}/scores_dev_2d.json"))), th2d["S"], th2d["R"])}
    items = GR.word_items(rows)
    wc = {n: GR.words_channel(items, d) for n, d in nat.items()}
    T = {n: S.unit_table(rows, d, sg) for n, d in nat.items()}
    paired = {}
    for a, b in (("2d", "2b ears"), ("2d", "2c ears"), ("2d", "old head")):
        for w in ("primary", "audio"):
            c = S.interval(T[a], T[b], w)
            paired[f"{a} - {b} ({w})"] = {"point": c["point"], "ci95": c["ci95"]}
    pts = GR.natural_points(rows, C.Context("dev"))
    rh = [p for p in pts if p["part"] == "r_hear"]
    hard = [p for p in rh if p["conf"] is not None and 0.5 <= p["conf"] < 0.9]
    quiet = [p for p in rh if not p["real"] and (p["conf"] is None or p["conf"] < 0.5)]
    stop_by_version = {}
    for part in ("s_move", "s_react"):
        for r in rows:
            if r["part"] != part:
                continue
            for p in r["points"]:
                g = p["gold"].get("S")
                if g is None:
                    continue
                for n, d in nat.items():
                    c = stop_by_version.setdefault(f"{part} v{r['version']} gold {g}", {}).setdefault(n, [0, 0])
                    c[0] += int(d.get((r["unit"], r["version"], p["k"]), {}).get("S") == g)
                    c[1] += 1
    res = {"words_channel": {n: {k: v for k, v in x.items() if not k.startswith("_")} for n, x in wc.items()},
           "paired": paired, "stop_by_version": stop_by_version,
           "hard_subset": {"n": len(hard), "n_real": int(sum(p["real"] for p in hard)),
                           **{n: float(np.mean([d.get(p["key"], {}).get("R") == p["gold"] for p in hard]))
                              for n, d in nat.items()}},
           "no_event_low_label_false_events": {"n": len(quiet), **{n: int(sum(d.get(p["key"], {}).get("R") != p["gold"]
                                                                              for p in quiet)) for n, d in nat.items()}},
           "trust": GR.natural_report(pts, nat)["trust"]}
    json.dump(res, open(f"{RES}/readout_2d_natural_dev.json", "w"), indent=1, default=str)
    for n, x in wc.items():
        print(f"words channel {n:9s} event-led {x['event_led_rate']:.3f} event-blind {x['event_blind_rate']:.3f}")
    for k, v in paired.items():
        print(f"{k}: {100 * v['point']:+.1f} [{100 * v['ci95'][0]:+.1f}, {100 * v['ci95'][1]:+.1f}]")
    for k, v in stop_by_version.items():
        print(f"{k}: " + ", ".join(f"{n} {c[0]}/{c[1]}" for n, c in v.items()))
    print("hard subset:", {k: (round(v, 3) if isinstance(v, float) else v) for k, v in res["hard_subset"].items()})
    print("no-event low-label false events:", res["no_event_low_label_false_events"])
    for band, row in res["trust"].items():
        print(f"trust {band}: " + json.dumps({k: (round(v, 3) if isinstance(v, float) else v) for k, v in row.items()}))


if __name__ == "__main__":
    if sys.argv[1] == "offsets":
        offsets(sys.argv[2] if len(sys.argv) > 2 else "dev")
    else:
        {"ears": ears, "fit": fit, "eval": eval_, "report": report}[sys.argv[1]]()
